  ["windowRulesHyprlang"] = "# Set float and centering for dialog boxes\nrule = float(true), match:modal:1\nrule = center(true), match:modal:1\n\nwindowrule {\n  name = Resolve\n  match:class = ^(\\bresolve\\b)$\n  match:xwayland = 1\n  no_blur = on\n}\n\nwindowrule {\n  name = Thunar\n  match:class = ^([Tt]hunar|org.gnome.Nautilus|[Pp]cmanfm-qt)$\n  tag = +file-manager\n}\n\nwindowrule {\n  name = Terminals\n  match:class = ^(com.mitchellh.ghostty|org.wezfurlong.wezterm|Alacritty|kitty|kitty-dropterm|dropterminal)$\n  suppress_event = fullscreen maximize\n  tag = +terminal\n}\n\nwindowrule {\n  name = Brave-browser\n  match:class = ^(Brave-browser(-beta|-dev|-unstable)?)$\n  tag = +browser\n}\n\nwindowrule {\n  name = Firefox\n  match:class = ^([Ff]irefox|org.mozilla.firefox|[Ff]irefox-esr)$\n  tag = +browser\n}\n\nwindowrule {\n  name = Google-chrome\n  match:class = ^([Gg]oogle-chrome(-beta|-dev|-unstable)?)$\n  tag = +browser\n}\n\nwindowrule {\n  name = Thorium-browser\n  match:class = ^([Tt]horium-browser|[Cc]achy-browser)$\n  tag = +browser\n}\n\nwindowrule {\n  name = vscodium\n  match:class = ^(codium|codium-url-handler|VSCodium)$\n  tag = +projects\n}\n\nwindowrule {\n  name = vscode\n  match:class = ^(VSCode|code-url-handler)$\n  tag = +projects\n}\n\nwindowrule {\n  name = Discord\n  match:class = ^([Dd]iscord|[Ww]ebCord|[Vv]esktop)$\n  tag = +im\n}\n\nwindowrule {\n  name = Ferdium\n  match:class = ^([Ff]erdium)$\n  center = on\n  float = on\n  size = 60% = 70%\n  tag = +im\n}\n\nwindowrule {\n  name = Whatsapp\n  match:class = ^([Ww]hatsapp-for-linux)$\n  tag = +im\n}\n\nwindowrule {\n  name = Telegram-desktop\n  match:class = ^(org.telegram.desktop|io.github.tdesktop_x64.TDesktop)$\n  tag = +im\n}\n\nwindowrule {\n  name = teams-for-linux\n  match:class = ^(teams-for-linux)$\n  tag = +im\n}\n\nwindowrule {\n  name = gamescope\n  match:class = ^(gamescope)$\n  tag = +games\n}\n\nwindowrule {\n  name = steam-app\n  match:class = ^(steam_app\\d+)$\n  tag = +games\n}\n\nwindowrule {\n  name = Steam\n  match:class = ^([Ss]team)$\n  tag = +gamestore\n}\n\nwindowrule {\n  name = Lutris\n  match:title = ^([Ll]utris)$\n  tag = +gamestore\n}\n\nwindowrule {\n  name = heroicgameslauncher\n  match:class = ^(com.heroicgameslauncher.hgl)$\n  tag = +gamestore\n}\n\nwindowrule {\n  name = gnome-disks\n  match:class = ^(gnome-disks|wihotspot(-gui)?)$\n  tag = +settings\n}\n\nwindowrule {\n  name = rofi\n  match:class = ^([Rr]ofi)$\n  tag = +settings\n  no_blur = off\n}\n\nwindowrule {\n  name = FileRoller\n  match:class = ^(file-roller|org.gnome.FileRoller)$\n  tag = +settings\n}\n\nwindowrule {\n  name = NetworkManger\n  match:class = ^(nm-applet|nm-connection-editor|blueman-manager)$\n  tag = +settings\n}\n\nwindowrule {\n  name = PlusAudio\n  match:class = ^(pavucontrol|org.pulseaudio.pavucontrol|com.saivert.pwvucontrol)$\n  center = on\n  tag = +settings\n  no_blur = off\n}\n\nwindowrule {\n  name = nwg-look\n  match:class = ^(nwg-look|qt5ct|qt6ct|[Yy]ad)$\n  tag = +settings\n}\n\nwindowrule {\n  name = xdg-desktop-portal-gtk\n  match:class = (xdg-desktop-portal-gtk)\n  tag = +settings\n}\n\nwindowrule {\n  name = blueman\n  match:class = (.blueman-manager-wrapped)\n  tag = +settings\n}\n\nwindowrule {\n  name = nwg-displays\n  match:class = (nwg-displays)\n  tag = +settings\n}\n\nwindowrule {\n  name = Picture-in-Picture\n  match:title = ^(Picture-in-Picture)$\n  float = on\n  move = 72% = 7%\n  opacity = 0.95 = 0.75\n  pin = 0\n  keep_aspect_ratio = on\n}\n\nwindowrule {\n  name = ThunarFileMgr\n  match:class = ([Tt]hunar)\n  match:title = negative:(.*[Tt]hunar.*)\n  center = on\n  float = on\n}\n\nwindowrule {\n  name = Authentication-Required\n  match:title = ^(Authentication Required)$\n  center = on\n  float = on\n}\n\nwindowrule {\n  name = Noctalia-Settings\n  match:class = ^(dev\\.noctalia\\.Noctalia)$\n  center = on\n  float = on\n  size = 70% = 70%\n  tag = +settings\n}\n\nwindowrule {\n  name = IdleInhibit-fullscreen-1\n  match:class = ^(.*)$\n  idle_inhibit = fullscreen\n}\n\nwindowrule {\n  name = IdleInhibit-fullscreen-2\n  match:title = ^(.*)$\n  idle_inhibit = fullscreen\n}\n\nwindowrule {\n  name = IdleInhibit-fullscreen-3\n  match:fullscreen = 1\n  idle_inhibit = fullscreen\n}\n\nwindowrule {\n  name = Settings-Tag\n  match:tag = settings*\n  float = on\n  opacity = 0.8 = 0.7\n  size = 70% = 70%\n  no_blur = off\n}\n\nwindowrule {\n  name = WayPaper\n  match:class = ^([Ww]aypaper)$\n  float = on\n  no_blur = off\n}\n\nwindowrule {\n  name = mpv-or-clapper\n  match:class = ^(mpv|com.github.rafostar.Clapper)$\n  float = on\n}\n\nwindowrule {\n  name = codium-url-handler\n  match:class = (codium|codium-url-handler|VSCodium)\n  match:title = negative:(.*codium.*|.*VSCodium.*)\n  float = on\n}\n\nwindowrule {\n  name = heroicgameslauncher-1\n  match:class = ^(com.heroicgameslauncher.hgl)$\n  match:title = negative:(Heroic Games Launcher)\n  float = on\n}\n\nwindowrule {\n  name = Steam\n  match:class = ^([Ss]team)$\n  match:title = negative:^([Ss]team)$\n  float = on\n}\n\nwindowrule {\n  name = Add-Folder\n  match:initial_title = (Add Folder to Workspace)\n  float = on\n  size = 70% = 60%\n}\n\nwindowrule {\n  name = Open-File\n  match:initial_title = (Open Files)\n  float = on\n  size = 70% = 60%\n}\n\nwindowrule {\n  name = Wants-to-Save\n  match:initial_title = (wants to save)\n  float = on\n}\n\nwindowrule {\n  name = Browsers\n  match:tag = browser*\n  opacity = 1.0 = 1.0\n}\n\nwindowrule {\n  name = Projects\n  match:tag = projects*\n  opacity = 0.9 = 0.8\n}\n\nwindowrule {\n  name = Instant-Messaging\n  match:tag = im*\n  opacity = 0.94 = 0.86\n}\n\nwindowrule {\n  name = File-Managers\n  match:tag = file-manager*\n  opacity = 0.9 = 0.8\n}\n\nwindowrule {\n  name = Terminals-opacity\n  match:tag = terminal*\n  opacity = 0.8 = 0.7\n  no_blur = off\n}\n\nwindowrule {\n  name = windowrule-77\n  match:class = ^(gedit|org.gnome.TextEditor|mousepad)$\n  opacity = 0.8 = 0.7\n}\n\nwindowrule {\n  name = windowrule-78\n  match:class = ^(seahorse)$\n  opacity = 0.9 = 0.8\n}\n\nwindowrule {\n  name = windowrule-79\n  match:tag = games*\n  no_blur = on\n}\n\nwindowrule {\n  name = windowrule-80\n  match:tag = games*\n  fullscreen = on\n}\n\nwindowrule {\n  name = qs-keybinds\n  match:title = ^(Hyprland Keybinds|Emacs Leader Keybinds|Kitty Configuration|WezTerm Configuration|Ghostty Configuration|Yazi Configuration)$\n  float = on\n  center = on\n  size = 55% = 66%\n}\n\nwindowrule {\n  name = qs-cheatsheets\n  match:title = ^(Cheatsheets Viewer)$\n  float = on\n  center = on\n  size = 65% = 60%\n}\n\nwindowrule {\n  name = qs-extended-viewers\n  match:title = ^(Hyprland Keybinds|Niri Keybinds|BSPWM Keybinds|i3 Keybinds|Sway Keybinds|DWM Keybinds|Emacs Leader Keybinds|Kitty Configuration|WezTerm Configuration|Ghostty Configuration|Yazi Configuration|Cheatsheets Viewer|Documentation Viewer)$\n  float = on\n  center = on\n  size = 55% = 66%\n}\n\nwindowrule {\n  name = QS-Wallpapers\n  match:class = ^(org\\.qt-project\\.qml)$\n  match:title = ^(Wallpapers)$\n  border_size = 0\n  float = on\n  no_blur = on\n  no_shadow = on\n  rounding = 12\n}\n\nwindowrule {\n  name = QA-Video-Wallpapers\n  match:class = ^(org\\.qt-project\\.qml)$\n  match:title = ^(Video Wallpapers)$\n  border_size = 0\n  center = on\n  float = on\n  no_blur = on\n  no_shadow = on\n  rounding = 12\n}\n\nwindowrule {\n  name = QS-wlogout\n  match:class = ^(org\\.qt-project\\.qml)$\n  match:title = ^(qs-wlogout)$\n  border_size = 0\n  center = on\n  float = on\n  opacity = 1.0 = 1.0\n  rounding = 20\n}\n\nwindowrule {\n  name = QA-Panels\n  match:class = ^(org\\.qt-project\\.qml)$\n  match:title = ^(Panels)$\n  center = on\n  float = on\n  no_blur = on\n  no_shadow = on\n  rounding = 12\n}\n\nwindowrule {\n  name = QS-Cheatsheets\n  match:class = ^(org\\.qt-project\\.qml)$\n  match:title = ^(Cheatsheets Viewer)$\n  border_size = 0\n  center = on\n  float = on\n  no_shadow =